DROP TABLE IF EXISTS `ai_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `instructor_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `product_note_id` bigint unsigned DEFAULT NULL,
  `source_type` varchar(255) NOT NULL,
  `source_name` varchar(255) NOT NULL,
  `original_path` varchar(255) NOT NULL,
  `storage_disk` varchar(255) NOT NULL DEFAULT 'bunny',
  `bunny_folder_path` varchar(255) DEFAULT NULL,
  `mime_type` varchar(255) DEFAULT NULL,
  `file_extension` varchar(32) DEFAULT NULL,
  `file_hash` varchar(64) NOT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `progress` tinyint unsigned NOT NULL DEFAULT '0',
  `page_count` int unsigned DEFAULT NULL,
  `character_count` int unsigned DEFAULT NULL,
  `extracted_text_path` longtext,
  `extracted_text_excerpt` text,
  `metadata` json DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `failed_at` timestamp NULL DEFAULT NULL,
  `failure_reason` longtext,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ai_documents_instructor_id_foreign` (`instructor_id`),
  KEY `ai_documents_product_id_foreign` (`product_id`),
  KEY `ai_documents_product_note_id_foreign` (`product_note_id`),
  KEY `ai_documents_file_hash_index` (`file_hash`),
  KEY `ai_documents_status_index` (`status`),
  CONSTRAINT `ai_documents_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ai_documents_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ai_documents_product_note_id_foreign` FOREIGN KEY (`product_note_id`) REFERENCES `product_notes` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

