INSERT INTO `email_templates` VALUES (1,'password_reset','Password Reset','<p>Dear {{user_name}},</p>\n                <p>Do you want to reset your password? Please Click the following link and Reset Your Password.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(2,'contact_mail','Contact Email','<p>Hello there,</p>\n                <p>&nbsp;Mr. {{name}} has sent a new message. you can see the message details below.&nbsp;</p>\n                <p>Email: {{email}}</p>\n                <p>Phone: {{phone}}</p>\n                <p>Subject: {{subject}}</p>\n                <p>Message: {{message}}</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(3,'subscribe_notification','Subscribe Notification','<p>Hi there, Congratulations! Your Subscription has been created successfully. Please Click the following link and Verified Your Subscription. If you will not approve this link, you can not get any newsletter from us.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(4,'user_verification','User Verification','<p>Dear {{user_name}},</p>\n                <p>Congratulations! Your Account has been created successfully. Please Click the following link and Active your Account.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(5,'approved_refund','Refund Request Approval','<p>Dear {{user_name}},</p>\n                <p>We are happy to say that, we have send {{refund_amount}} USD to your provided bank information. </p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(6,'new_refund','New Refund Request','<p>Hello websolutionus, </p>\n\n                <p>Mr. {{user_name}} has send a new refund request to you.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(7,'pending_wallet_payment','Wallet Payment Approval','<p>Hello {{user_name}},</p>\n                <p>We have received your wallet payment request. we find your payment to our bank account.</p>\n                <p>Thanks &amp; Regards</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(8,'approved_withdraw','Withdraw Request Approval','<p>Dear {{user_name}},</p>\n                <p>We are happy to say that, we have send a withdraw amount to your provided bank information.</p>\n                <p>Thanks &amp; Regards</p>\n                <p>WebSolutionUs</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(9,'rejected_withdraw','Withdraw Request Rejected','<p>Dear {{user_name}},</p>\n                <p> your withdraw request has been rejected.</p>\n                <p>Thanks &amp; Regards</p>\n                <p>WebSolutionUs</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(10,'pending_withdraw','Withdraw Request Pending','<p>Dear {{user_name}},</p>\n                <p> your withdraw request is waiting for approval.</p>\n                <p>Thanks &amp; Regards</p>\n                <p>WebSolutionUs</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(11,'instructor_request_approved','Instructor Request Approval','<p>Dear {{user_name}},</p>\n                <p>you are now approved as an instructor.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(12,'instructor_request_rejected','Instructor Request Rejected','<p>Dear {{user_name}},</p>\n                <p>your request has been rejected. please resubmit your request with proper document. or contact us.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(13,'instructor_request_pending','Instructor Request is waiting for approval','<p>Dear {{user_name}},</p>\n                <p>your request for become an instructor is waiting for approval. please wait. we will send you an email when your request is approved.</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(14,'instructor_quick_contact','Mail for instructor contact form','<p>Name: {{name}}</p>\n                <p>Email: {{email}}</p>\n                <p>Subject: {{subject}}</p>\n                <p>{{message}}</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(15,'order_completed','Your order has been placed','<p>HI, {{name}}</p>\n                <p>Invoice ID: {{order_id}}</p>\n                <p>paid amount: {{paid_amount}}</p>\n                <p>payment method: {{payment_method}}</p>','2024-06-03 02:02:30','2024-06-03 02:02:30'),(16,'qna_reply_mail','QNA Replay mail','<p>Hi {{user_name}}, your instructor has replied to your question. Please see the answer below:</p>\r\n<p>Course: {{course}}</p>\r\n<p>Lesson: {{lesson}}</p>\r\n<p>Question: {{question}}</p>','2024-08-25 03:36:19','2024-08-25 03:36:19'),(17,'live_class_mail','Live class notification mail','<p>Hi {{user_name}},</p>\r\n                <p>Your live class is starting at {{start_time}}. Please see the details below:</p>\r\n                <p><strong>Course:</strong> {{course}}</p>\r\n                <p><strong>Lesson:</strong> {{lesson}}</p>\r\n                <p><strong>Meeting Link:</strong> <a href=\"{{join_url}}\">{{join_url}}</a></p>','2024-09-03 12:51:51','2024-09-03 12:51:51'),(18,'payment_status','Update Payment Status','<p>HI, {{name}}</p>\n<p>Invoice ID: {{order_id}}</p>\n<p>paid amount: {{paid_amount}}</p>\n<p>payment status: {{payment_status}}</p>','2024-06-02 20:02:30','2024-06-02 20:02:30'),(19,'gift_course','Gift Course Notification','<p>Hi {{name}},</p><p>{{sender_name}} has gifted you a course! Click the link below to enroll and claim your course. <strong>Do not share this link with anyone.</strong></p><p><strong>Claim Course:</strong> <a href=\"{{link}}\">{{link}}</a></p><p><strong>Visit Course:</strong> <a href=\"{{course_link}}\">{{course_name}}</a></p><p><strong>Sender Email:</strong> {{sender_email}}</p><p><strong>Message from Sender:</strong> {{message}}</p><p>Enjoy your learning!</p>','2024-06-02 20:02:30','2024-06-02 20:02:30'),(20,'rejected_refund','Refund Request Rejected','<p>Dear {{user_name}},</p>\r\n<p>We are sorry to say that your request for refund is rejected. Order NO: #{{invoice_id}}</p>','2025-08-19 22:53:52','2025-08-19 16:59:30');
/*!40000 ALTER TABLE `email_templates` ENABLE KEYS */;
UNLOCK TABLES;

