INSERT INTO `faq_translations` VALUES (1,1,'en','What kind of courses do you offer?','We offer a wide range of courses in various subjects,\r\n from business and technology to art and personal development. You can browse our extensive catalog to find a course that interests you.','2024-06-04 05:49:36','2024-06-04 05:49:36'),(2,1,'hi','आप किस प्रकार के पाठ्यक्रम पेश करते हैं?','हम विभिन्न विषयों में पाठ्यक्रमों की एक विस्तृत श्रृंखला प्रदान करते हैं,\r\n व्यवसाय और प्रौद्योगिकी से लेकर कला और व्यक्तिगत विकास तक। आप अपनी रुचि का पाठ्यक्रम ढूंढने के लिए हमारी विस्तृत सूची ब्राउज़ कर सकते हैं।','2024-06-04 05:49:36','2024-06-04 05:50:00'),(3,1,'ar','ما نوع الدورات التي تقدمها؟','نحن نقدم مجموعة واسعة من الدورات في مختلف المواضيع،\r\n من الأعمال والتكنولوجيا إلى الفن والتنمية الشخصية. يمكنك تصفح الكتالوج الشامل الخاص بنا للعثور على الدورة التدريبية التي تهمك.','2024-06-04 05:49:36','2024-06-04 05:50:20'),(4,2,'en','Who are your instructors?','Our instructors are industry experts and passionate educators with a wealth of knowledge and experience.\r\n You can learn more about their qualifications on their course profiles.','2024-06-04 05:50:58','2024-06-04 05:50:58'),(5,2,'hi','आपके प्रशिक्षक कौन हैं?','हमारे प्रशिक्षक उद्योग विशेषज्ञ और समृद्ध ज्ञान और अनुभव वाले भावुक शिक्षक हैं।\r\n आप उनकी पाठ्यक्रम प्रोफ़ाइल पर उनकी योग्यताओं के बारे में अधिक जान सकते हैं।','2024-06-04 05:50:58','2024-06-04 05:58:27'),(6,2,'ar','من هم معلميك؟','المدربون لدينا هم خبراء في الصناعة ومعلمون متحمسون يتمتعون بثروة من المعرفة والخبرة.\r\n يمكنك معرفة المزيد حول مؤهلاتهم في ملفات تعريف الدورة التدريبية الخاصة بهم.','2024-06-04 05:50:58','2024-06-04 05:52:04'),(7,3,'en','How much do your courses cost?','Course prices vary depending on the length, content, and instructor. We offer free trials and introductory courses in some cases. Check the individual course page for specific pricing information.','2024-06-04 05:53:19','2024-06-04 05:53:19'),(8,3,'hi','आपके पाठ्यक्रमों की लागत कितनी है?','पाठ्यक्रम की कीमतें लंबाई, सामग्री और प्रशिक्षक के आधार पर भिन्न होती हैं। हम कुछ मामलों में निःशुल्क परीक्षण और परिचयात्मक पाठ्यक्रम प्रदान करते हैं। विशिष्ट मूल्य निर्धारण जानकारी के लिए व्यक्तिगत पाठ्यक्रम पृष्ठ देखें।','2024-06-04 05:53:19','2024-06-04 05:53:58'),(9,3,'ar','كم تكلفة الدورات الخاصة بك؟','تختلف أسعار الدورة حسب الطول والمحتوى والمدرب. نحن نقدم تجارب مجانية ودورات تمهيدية في بعض الحالات. تحقق من صفحة الدورة التدريبية الفردية للحصول على معلومات التسعير المحددة.','2024-06-04 05:53:19','2024-06-04 05:54:19'),(10,4,'en','How does the online learning platform work?','Our platform is user-friendly and accessible on any device. You can enroll in courses, access learning materials, interact with instructors and classmates, and track your progress, all in one place.','2024-06-04 05:54:52','2024-06-04 05:54:52'),(11,4,'hi','ऑनलाइन लर्निंग प्लेटफॉर्म कैसे काम करता है?','हमारा प्लेटफ़ॉर्म उपयोगकर्ता के अनुकूल है और किसी भी डिवाइस पर पहुंच योग्य है। आप पाठ्यक्रमों में नामांकन कर सकते हैं, शिक्षण सामग्री तक पहुंच सकते हैं, प्रशिक्षकों और सहपाठियों के साथ बातचीत कर सकते हैं और अपनी प्रगति को ट्रैक कर सकते हैं, यह सब एक ही स्थान पर।','2024-06-04 05:54:52','2024-06-04 05:55:10'),(12,4,'ar','كيف تعمل منصة التعلم عبر الإنترنت؟','منصتنا سهلة الاستخدام ويمكن الوصول إليها على أي جهاز. يمكنك التسجيل في الدورات التدريبية، والوصول إلى المواد التعليمية، والتفاعل مع المعلمين وزملاء الدراسة، وتتبع تقدمك، كل ذلك في مكان واحد.','2024-06-04 05:54:53','2024-06-04 05:55:29');
/*!40000 ALTER TABLE `faq_translations` ENABLE KEYS */;
UNLOCK TABLES;

