INSERT INTO `featured_instructor_translations` VALUES (1,1,'en','Our Top Class & Expert Instructors in One Place','Combines the ideas of empowered learning and top-tier instruction for students. Emphasizes both instructor expertise','See All Instructors','2024-06-04 05:22:14','2024-06-04 05:24:22'),(2,1,'hi','हमारे शीर्ष श्रेणी और विशेषज्ञ प्रशिक्षक एक ही स्थान पर','छात्रों के लिए सशक्त शिक्षा और शीर्ष स्तरीय निर्देश के विचारों को जोड़ता है। दोनों प्रशिक्षक विशेषज्ञता पर जोर देता है','सभी प्रशिक्षक देखें','2024-06-04 05:22:14','2024-06-04 05:24:43'),(3,1,'ar','لدينا أفضل المدربين والخبراء في مكان واحد','يجمع بين أفكار التعلم المُمكّن والتعليم عالي المستوى للطلاب. يؤكد على خبرة المدرب','شاهد جميع المدربين','2024-06-04 05:22:14','2024-06-04 05:25:09');
