INSERT INTO `section_translations` VALUES (1,1,'en','{\"title\": \"Never Stop [Learning]\\\\Life {Never Stop} Teaching\", \"sub_title\": \"Every teaching and learning journey is unique Following\\\\We\'ll help guide your way.\", \"total_student\": \"80k\", \"total_instructor\": \"30k\", \"video_button_text\": \"Watch Our\\\\Class Demo\", \"action_button_text\": \"Check Our Courses\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(2,1,'hi','{\"title\": \"कभी न रुकें [सीखना] जीवन कभी भी सिखाना बंद न करें\", \"sub_title\": \"प्रत्येक शिक्षण और सीखने की यात्रा अद्वितीय है, निम्नलिखित\\\\हम ​​आपका मार्गदर्शन करने में मदद करेंगे।\", \"total_student\": \"80k\", \"total_instructor\": \"30k\", \"video_button_text\": \"हमारा\\\\क्लास डेमो देखें\", \"action_button_text\": \"हमारे पाठ्यक्रम जांचें\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(3,1,'ar','{\"title\": \"لا تتوقف أبدًا عن [التعلم] الحياة لا تتوقف أبدًا عن التدريس\", \"sub_title\": \"تعتبر كل رحلة تعليم وتعلم فريدة من نوعها. سنساعدك في توجيه طريقك.\", \"total_student\": \"80k\", \"total_instructor\": \"30k\", \"video_button_text\": \"شاهد العرض التوضيحي الخاص بفصلنا\", \"action_button_text\": \"تحقق من دوراتنا\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(4,2,'en','{\"title\": \"Thousand Of Top [Courses]\\\\Now in One Place\", \"button_text\": \"More Info\", \"description\": \"<p class=\\\"\\\\&quot;desc\\\\&quot;\\\">Discover a vast collection of top-rated courses, covering a wide range of subjects and taught by expert instructors. Whether you\'re looking to advance your career</p>\\r\\n<ul>\\r\\n<li class=\\\"\\\\&quot;content\\\\&quot;\\\">The Most World Class Instructors</li>\\r\\n<li class=\\\"\\\\&quot;content\\\\&quot;\\\">Access Your Class anywhere</li>\\r\\n<li class=\\\"\\\\&quot;content\\\\&quot;\\\">Flexible Course Price</li>\\r\\n</ul>\", \"short_title\": \"Get More About Us\"}','2024-10-15 21:42:24','2024-10-15 21:48:06'),(5,2,'hi','{\"title\": \"हजारों शीर्ष पाठ्यक्रम अब एक ही स्थान पर\", \"button_text\": \"और जानकारी\", \"description\": \"<p>विशेषज्ञ प्रशिक्षकों द्वारा पढ़ाए जाने वाले उच्च-रेटेड पाठ्यक्रमों का एक विशाल संग्रह खोजें, जो विभिन्न विषयों को कवर करते हैं। चाहे आप अपने करियर को आगे बढ़ाना चाहते हों, नई कौशल सीखना चाहते हों, या किसी शौक का पता लगाना चाहते हों, आपको अपनी आवश्यकताओं के अनुरूप लचीले और किफायती विकल्प मिलेंगे।</p>\\r\\n<ul>\\r\\n<li><strong>विश्व स्तरीय प्रशिक्षक</strong>: दुनिया के सर्वश्रेष्ठ प्रशिक्षकों से सीखें।</li>\\r\\n<li><strong>कहीं भी पहुंचें</strong>: कहीं भी और कभी भी अपने कक्षाओं का आनंद लें।</li>\\r\\n<li><strong>लचीली कीमतें</strong>: अपने बजट के अनुसार पाठ्यक्रम चुनें।</li>\\r\\n</ul>\\r\\n<pre id=\\\"\\\\&quot;tw-target-text\\\\&quot;\\\" class=\\\"\\\\&quot;tw-data-text\\\" dir=\\\"\\\\&quot;ltr\\\\&quot;\\\" data-placeholder=\\\"\\\\&quot;Translation\\\\&quot;\\\" aria-label=\\\"\\\\&quot;Translated\\\" data-ved=\\\"\\\\&quot;2ahUKEwjxxcKXk8CGAxVioGMGHZUBOvUQ3ewLegQIBxAT\\\\&quot;\\\"><span class=\\\"\\\\&quot;Y2IQFc\\\\&quot;\\\" lang=\\\"\\\\&quot;hi\\\\&quot;\\\">&nbsp;</span></pre>\", \"short_title\": \"हमारे बारे में अधिक जानें\"}','2024-10-15 21:42:24','2024-10-15 21:48:43'),(6,2,'ar','{\"title\": \"آلاف من أفضل الدورات التدريبية الآن في مكان واحد\", \"button_text\": \"مزيد من المعلومات\", \"description\": \"<p>آلاف الدورات الأعلى الآن في مكان واحد</p>\\r\\n<p>اكتشف مجموعة واسعة من الدورات الأعلى تقييمًا، تغطي مجموعة متنوعة من المواضيع وتُدرَّس بواسطة مدربين خبراء. سواء كنت ترغب في تطوير مسيرتك المهنية، تعلم مهارة جديدة، أو استكشاف هواية، ستجد خيارات مرنة ومناسبة لاحتياجاتك.</p>\\r\\n<ul>\\r\\n<li>أفضل المدربين عالميًا**: تعلم من أفضل المدربين في العالم.</li>\\r\\n<li>الوصول إلى الدورات من أي مكان**: استمتع بدوراتك في أي وقت ومن أي مكان.</li>\\r\\n<li>أسعار مرنة للدورات**: اختر الدورات التي تناسب ميزانيتك.</li>\\r\\n</ul>\", \"short_title\": \"تعرف على المزيد عنا\"}','2024-10-15 21:42:24','2024-10-15 21:49:27'),(7,5,'en','{\"title\": \"Start Learning From World’s Pro Instructors\", \"description\": \"Groove’s intuitive shared inbox makes it easy for team members to organize, prioritize and.In this episode.\", \"short_title\": \"FAQs\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(8,5,'hi','{\"title\": \"दुनिया के प्रो प्रशिक्षकों से सीखना शुरू करें\", \"description\": \"ग्रूव का सहज साझा इनबॉक्स टीम के सदस्यों के लिए व्यवस्थित करना, प्राथमिकता देना और आसान बनाता है।\", \"short_title\": \"FAQs\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(9,5,'ar','{\"title\": \"ابدأ التعلم من المدربين المحترفين في العالم\", \"description\": \"يجعل صندوق الوارد المشترك البديهي في Groove من السهل على أعضاء الفريق تنظيم مهامهم وتحديد أولوياتها. في هذه الحلقة.\", \"short_title\": \"FAQs\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(10,6,'en','{\"title_one\": \"Learn with Experts\", \"title_two\": \"Learn Anything\", \"title_four\": \"E-mail Marketing\", \"title_three\": \"Get Online Certificate\", \"sub_title_one\": \"Elevate your learning. Trusted guidance, real results\", \"sub_title_two\": \"Master Any Skill. Unleash Your Potential and join the best\", \"sub_title_four\": \"Grow Your Business. Reach New Customers\", \"sub_title_three\": \"Master in Demand Skills. Soon Get Certified Today\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(11,6,'hi','{\"title_one\": \"विशेषज्ञों से सीखें\", \"title_two\": \"कुछ भी सीखें\", \"title_four\": \"ईमेल व्यापार\", \"title_three\": \"ऑनलाइन प्रमाणपत्र प्राप्त करें\", \"sub_title_one\": \"अपनी शिक्षा को उन्नत करें. विश्वसनीय मार्गदर्शन, वास्तविक परिणाम\", \"sub_title_two\": \"किसी भी कौशल में महारत हासिल करें। अपनी क्षमता को उजागर करें\", \"sub_title_four\": \"अपना व्यवसाय बढ़ाएं. नए ग्राहकों तक पहुंचें\", \"sub_title_three\": \"मांग कौशल में मास्टर. आज ही प्रमाणित हो जाएं\"}','2024-10-15 21:42:24','2024-10-15 21:42:24'),(12,6,'ar','{\"title_one\": \"تعلم مع الخبراء\", \"title_two\": \"تعلم أي شيء\", \"title_four\": \"التسويق عبر البريد الإلكتروني\", \"title_three\": \"الحصول على شهادة عبر الإنترنت\", \"sub_title_one\": \"ارفع مستوى تعلم