INSERT INTO `testimonial_translations` VALUES (1,1,'en','Sarah K','Marketing Manager','I was hesitant about online learning at first, but this platform has completely changed my mind. The courses are well-organized and informative,','2024-06-04 06:18:56','2024-06-04 06:20:19'),(2,1,'hi','सारा के','विपणन प्रबंधक','मैं पहले ऑनलाइन सीखने से झिझक रहा था, लेकिन इस मंच ने मेरा मन पूरी तरह से बदल दिया है। पाठ्यक्रम सुव्यवस्थित और जानकारीपूर्ण हैं,','2024-06-04 06:18:56','2024-06-04 06:20:56'),(3,1,'ar','سارة ك','مدير تسويق','كنت مترددًا بشأن التعلم عبر الإنترنت في البداية، لكن هذه المنصة غيرت رأيي تمامًا. الدورات منظمة تنظيما جيدا وغنية بالمعلومات،','2024-06-04 06:18:56','2024-06-04 06:21:22'),(4,2,'en','David L','Accountant','I took the \'Excel for Beginners\' course and was amazed at how much I learned in such a short time. The instructor explained everything clearly','2024-06-04 06:22:18','2024-06-04 06:22:18'),(5,2,'hi','डेविड एल.','मुनीम','मैंने \'एक्सेल फॉर बिगिनर्स\' कोर्स लिया और यह देखकर आश्चर्यचकित रह गया कि मैंने इतने कम समय में कितना कुछ सीखा। प्रशिक्षक ने सब कुछ स्पष्ट रूप से समझाया','2024-06-04 06:22:18','2024-06-04 06:22:39'),(6,2,'ar','ديفيد ل.','محاسب','لقد التحقت بدورة \"Excel للمبتدئين\" واندهشت من مقدار ما تعلمته في مثل هذا الوقت القصير. وأوضح المدرب كل شيء بوضوح','2024-06-04 06:22:18','2024-06-04 06:23:01'),(7,3,'en','Emily S','Social Media Specialist','I had the pleasure of taking a course on social media marketing taught by Instructor Their expertise in the field was evident  and their passion','2024-06-04 06:24:22','2024-06-04 06:25:50'),(8,3,'hi','एमिली एस','सोशल मीडिया विशेषज्ञ','मुझे प्रशिक्षक द्वारा पढ़ाए गए सोशल मीडिया मार्केटिंग पर पाठ्यक्रम लेने का सौभाग्य मिला, क्षेत्र में उनकी विशेषज्ञता स्पष्ट थी','2024-06-04 06:24:22','2024-06-04 06:24:42'),(9,3,'ar','إميلي س','أخصائي وسائل الاعلام الاجتماعية','لقد كان من دواعي سروري أن أتلقى دورة تدريبية حول التسويق عبر وسائل التواصل الاجتماعي قام بتدريسها المدرب وكانت خبرتهم في هذا المجال واضحة','2024-06-04 06:24:22','2024-06-04 06:25:03'),(10,4,'en','Alex J','Marketing Specialist','This platform has completely transformed my learning experience. The courses are well-structured, the content is top-notch, and the instructors are truly experts in their fields.','2024-06-04 06:24:22','2024-06-04 06:25:50'),(11,4,'hi','एलेक्स जे','विपणन विशेषज्ञ','इस प्लेटफ़ॉर्म ने मेरे सीखने के अनुभव को पूरी तरह से बदल दिया है। पाठ्यक्रम अच्छी तरह से संरचित हैं, सामग्री शीर्ष स्तर की है, और प्रशिक्षक वास्तव में अपने क्षेत्रों में विशेषज्ञ हैं।','2024-06-04 06:24:22','2024-06-04 06:24:42'),(12,4,'ar','اليكس ج','أخصائي التسويق','لقد غيرت هذه المنصة تجربتي التعليمية بشكل كامل. الدورات منظمة بشكل جيد، والمحتوى من الدرجة الأولى، والمدرسون خبراء حقًا في مجالاتهم.','2024-06-04 06:24:22','2024-06-04 06:24:42');
/*!40000 ALTER TABLE `testimonial_translations` ENABLE KEYS */;
UNLOCK TABLES;

